head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70011";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70011.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fnSubmit_onclick
 * @description 「전송」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSubmit_onclick = async function(e){
    try {
        await scwin.fnSubmit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70011.btn_fnSubmit_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70011.btn_window_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSubmit
 * @description fn Submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSubmit",
        method: "post",
        action: "/discls/disclosure.do",
        ref: "dma_fnSubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSubmit
 * @description fn Submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSubmit = async function () {
    const isSecureDocumnet = "Y";
    $c.util.getComponent('dma_fnSubmitReq').set('isSecureDocumnet', isSecureDocumnet);

    await scwin.tx_fnSubmit();
};
